class Gradebook:
    def __init__(self) -> None:
        """
        Initialize an empty gradebook.
        """
        self.assignments = {}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """
        Add an assignment to the gradebook.

        Args:
        name (str): Name of the assignment.
        weight (float): Weight of the assignment.
        kind (str, optional): Type of assignment ("homework" or "quiz"). Defaults to "homework".
        """
        if kind not in ["homework", "quiz"]:
            raise ValueError("Invalid assignment kind. Must be 'homework' or 'quiz'.")
        self.assignments[name] = {"weight": weight, "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        """
        Record a grade for a student on a specific assignment.

        Args:
        student (str): Name of the student.
        assignment (str): Name of the assignment.
        grade (float): Grade of the student on the assignment.

        Raises:
        ValueError: If the grade is outside the 2.0-5.0 scale.
        """
        if not 2.0 <= grade <= 5.0:
            raise ValueError("Grade must be between 2.0 and 5.0.")
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        """
        Calculate the average grade of a student.

        Args:
        student (str): Name of the student.

        Returns:
        float: Average grade of the student, rounded to two decimal places.
        """
        if student not in self.grades:
            return 0.0
        total_weight = 0
        total_grade = 0
        quiz_grades = []
        for assignment, details in self.assignments.items():
            if assignment in self.grades[student]:
                grade = self.grades[student][assignment]
            else:
                grade = 2.0
            if details["kind"] == "quiz":
                quiz_grades.append(grade)
            total_weight += details["weight"]
            total_grade += grade * details["weight"]
        if quiz_grades:
            quiz_grades.sort()
            total_grade -= min(quiz_grades)
            total_weight -= self.assignments[quiz_grades.index(min(quiz_grades)) + 1]["weight"]
        return round(total_grade / total_weight, 2)
